'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{PDFDocument}=require('pdf-lib'),Excel=require('exceljs');
const {createApp}=require('../lib/app'),{connect}=require('../lib/database'),{Service}=require('../lib/service');
const enabled=process.env.RUN_MYSQL_TESTS==='true';
async function setup(t){const config={configured:true,production:false,port:3000,host:'127.0.0.1',dbHost:'127.0.0.1',dbPort:3307,dbUser:'root',dbPassword:'',dbName:'jx_workflow_'+crypto.randomUUID().slice(0,8).replaceAll('-','')+'_test',publicUrl:'http://localhost:3000',sessionSecret:'workflow-test-session-secret-32-characters',secureCookie:false,adminUsername:'nodeadmin',adminPassword:'Test-only-password-2026'};const pool=await connect(config,true),app=await createApp(config,pool),server=app.listen(0,'127.0.0.1');await new Promise(r=>server.once('listening',r));t.after(async()=>{await new Promise(r=>server.close(r));await pool.query('DROP DATABASE ??',[config.dbName]);await pool.end();});const base='http://127.0.0.1:'+server.address().port;let cookie='',csrf='';async function req(path,method='GET',body){const headers={Cookie:cookie};if(method!=='GET')headers['X-CSRF-TOKEN']=csrf;if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body);}const r=await fetch(base+'/api'+path,{method,headers,body});if(r.headers.getSetCookie().length)cookie=r.headers.getSetCookie()[0].split(';')[0];const data=r.headers.get('content-type')?.includes('json')?await r.json():Buffer.from(await r.arrayBuffer());if(data.csrf)csrf=data.csrf;return {status:r.status,data};}await req('/auth');assert.equal((await req('/login','POST',{username:'nodeadmin',password:'Test-only-password-2026'})).status,200);await req('/auth');return {req,pool,service:new Service(pool,config.publicUrl)};}
test('MySQL workflow: print is read-only; completion updates QR state atomically and keeps history', {skip:!enabled},async t=>{const {req,service}=await setup(t),tag='Workflow-'+crypto.randomUUID();const p=(await req('/products','POST',{customer:{name:tag,address:'Test road'},company:'DE',product_type:'ATS',brand:'test',model:'m',serial_no:tag,details:{new_reg:'OLD0001'}})).data;assert.equal(p.brand,'TEST');assert.equal(p.name,tag.toUpperCase());assert.equal((await service.products('old 0001',0)).items[0].id,p.id);const qr=(await req('/products/'+p.id+'/qr')).data.link;
const input={company:'DE',product_ids:[p.id],stamping_date:'2026-11-05',request_id:crypto.randomUUID(),product_versions:{[p.id]:p.version},customer_versions:{[p.id]:p.customer_version},product_overrides:{[p.id]:{details:{new_reg:'NEW0002'}}},list_entries:{[p.id]:{stamping_fee:'12.50'}}};const initial=Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n);assert.equal((await req('/jobs/preview','POST',input)).status,200);assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n),initial);assert.equal((await req('/products/'+p.id)).data.details.new_reg,'OLD0001');
 const result=await req('/jobs/complete','POST',input);assert.equal(result.status,200,JSON.stringify(result.data));const current=(await req('/products/'+p.id)).data;assert.equal(current.details.new_reg,'NEW0002');assert.equal(current.details.old_reg,'OLD0001');assert.equal(current.details.last_date,'2026-11-05');assert.equal(current.details.stamping_fee,'12.50');assert.equal((await req('/products/'+p.id+'/qr')).data.link,qr);assert.equal((await req('/jobs/complete','POST',input)).data.id,result.data.id);assert.equal((await req('/products/'+p.id)).data.version,current.version);
 const snapshot=(await req('/jobs/'+result.data.id)).data.snapshot;assert.equal(snapshot.products[0].details.old_reg,'OLD0001');assert.equal(snapshot.products[0].details.new_reg,'NEW0002');const records=(await req('/records?from=2026-11-05&to=2026-11-05')).data;assert.ok(records.items.some(x=>x.job_id===result.data.id));assert.equal((await req('/records?from=2026-12-01&to=2026-01-01')).status,400);const exported=await req('/records/export.xlsx?from=2026-11-05&to=2026-11-05'),wb=new Excel.Workbook();await wb.xlsx.load(exported.data);assert.ok(wb.worksheets[0].getSheetValues().slice(2).some(row=>row[2]===p.name));const before=Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n);assert.equal((await req('/jobs/complete','POST',{...input,request_id:crypto.randomUUID()})).status,409);assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n),before);
});
test('MySQL workflow: background upload supports back pages; layout edits validate and preserve historical PDFs',{skip:!enabled},async t=>{const {req}=await setup(t),path='/admin/templates/MCM/ATP';let meta=(await req(path)).data;const oldProduct=(await req('/products','POST',{customer:{name:'TEMPLATE HISTORY',address:'ROAD'},company:'MCM',product_type:'ATP',brand:'TEST',model:'M',serial_no:crypto.randomUUID(),details:{}})).data;const oldJob=(await req('/jobs','POST',{company:'MCM',product_ids:[oldProduct.id],stamping_date:'2026-11-05',request_id:crypto.randomUUID()})).data;const oldPdf=(await req('/jobs/'+oldJob.id+'/pdf')).data;const doc=await PDFDocument.create();doc.addPage([595,842]);doc.addPage([595,842]);const form=new FormData();form.append('version',String(meta.version));form.append('file',new Blob([await doc.save()],{type:'application/pdf'}),'new-background.pdf');const upload=await req(path+'/background','POST',form);assert.equal(upload.status,200,JSON.stringify(upload.data));meta=upload.data;assert.equal(meta.pages,2);assert.equal(meta.width,595);assert.ok(oldPdf.equals((await req('/jobs/'+oldJob.id+'/pdf')).data),'Uploading a background must not replace historical PDFs');const invalid=structuredClone(meta.layout);invalid.fields.owner=[10000,10000,20,20];assert.equal((await req(path,'PUT',{version:meta.version,layout:invalid})).status,400);const preview=await req(path+'/preview','POST',{layout:meta.layout});assert.equal(preview.status,200,JSON.stringify(preview.data));assert.equal((await PDFDocument.load(preview.data)).getPageCount(),2);const changed=structuredClone(meta.layout);changed.fields.owner=[40,240,180,50];assert.equal((await req(path,'PUT',{version:meta.version,layout:changed})).status,200);assert.equal((await req(path,'PUT',{version:meta.version,layout:changed})).status,409);});

test('MySQL workflow: a failed multi-product completion rolls back customer and product changes',{skip:!enabled},async t=>{const {req,service}=await setup(t),tag='Rollback '+crypto.randomUUID(),products=[];for(let i=0;i<2;i++)products.push((await req('/products','POST',{customer:{name:tag,address:'ROAD'},company:'DE',product_type:'ATS',brand:'TEST',model:'M',serial_no:'SN'+i,details:{}})).data);const customerBefore=await service.customer(products[0].customer_id),input={company:'DE',stamping_date:'2026-11-05',product_ids:products.map(p=>p.id),request_id:crypto.randomUUID(),product_versions:Object.fromEntries(products.map(p=>[p.id,p.version])),customer_versions:Object.fromEntries(products.map(p=>[p.id,p.customer_version])),product_overrides:Object.fromEntries(products.map(p=>[p.id,{serial_no:'COLLISION',name:'CHANGED CUSTOMER'}]))};const result=await req('/jobs/complete','POST',input);assert.equal(result.status,409);assert.equal((await service.customer(customerBefore.id)).name,customerBefore.name);assert.equal((await service.customer(customerBefore.id)).version,customerBefore.version);for(const p of products){const after=await service.product(p.id);assert.equal(after.serial_no,p.serial_no);assert.equal(after.version,p.version);}assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n),0);});

test('MySQL workflow: phone delivery revisions require receiver confirmation and allow resending a product',{skip:!enabled},async t=>{const {req,service}=await setup(t),p=(await req('/products','POST',{customer:{name:'SYNC TEST',address:'ROAD'},company:'DE',product_type:'ATS',brand:'TEST',model:'M',serial_no:crypto.randomUUID(),details:{}})).data;const pair=(await req('/pairs','POST')).data,token=new URLSearchParams(new URL(pair.link).hash.slice(1)).get('pair'),accepted=(await req('/pairs/'+pair.id+'/accept','POST',{pair:token})).data;assert.ok(accepted.expires_at.endsWith('Z'));const send=()=>req('/pairs/'+pair.id+'/items','POST',{mobile:accepted.mobile,product:p.id});const first=await send();assert.equal(first.status,200);assert.equal(first.data.delivery_version,1);const status=version=>req('/pairs/'+pair.id+'/delivery-status','POST',{mobile:accepted.mobile,product:p.id,version});assert.equal((await status(1)).data.received,false);await assert.rejects(service.acknowledgeDeliveries(pair.id,{items:[{product_id:p.id,version:1}]},'not-the-owner'),/Record not found/);assert.equal((await req('/pairs/'+pair.id+'/ack','POST',{items:[{product_id:p.id,version:1}]})).status,200);assert.equal((await status(1)).data.received,true);const second=await send();assert.equal(second.data.delivery_version,2);assert.equal((await status(2)).data.received,false);const pending=(await req('/pairs/'+pair.id)).data.items;assert.equal(pending.length,1);assert.equal(pending[0].delivery_version,2);assert.equal(pending[0].delivery_acknowledged,1);await req('/pairs/'+pair.id+'/ack','POST',{items:[{product_id:p.id,version:100}]});assert.equal((await status(2)).data.received,true);assert.equal((await req('/pairs/'+pair.id+'/delivery-status','POST',{mobile:'wrong',product:p.id,version:2})).status,410);assert.equal((await service.product(p.id)).version,p.version);await req('/pairs/'+pair.id,'DELETE');assert.equal((await send()).status,410);assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_scan_deliveries')).n),0);});

test('MySQL workflow: named devices show presence, retain pairing thirty days and bind the phone employee',{skip:!enabled},async t=>{const {req,service}=await setup(t),pair=(await req('/pairs','POST',{device_name:'Office PC'})).data,token=new URLSearchParams(new URL(pair.link).hash.slice(1)).get('pair'),accepted=(await req('/pairs/'+pair.id+'/accept','POST',{pair:token,device_name:'Alice phone'})).data;assert.equal(accepted.devices.length,2);assert.ok(Date.parse(accepted.expires_at)>Date.now()+29*24*60*60*1000);let state=(await req('/pairs/'+pair.id)).data;assert.equal(state.devices.find(d=>d.role==='computer').name,'Office PC');assert.equal(state.devices.find(d=>d.role==='phone').name,'Alice phone');assert.ok(state.devices.every(d=>d.online));const names=(await req('/pairs')).data;assert.equal(names[0].desktop_name,'Office PC');assert.equal(names[0].mobile_name,'Alice phone');await service.q('UPDATE app_pair_devices SET mobile_seen_at=DATE_SUB(NOW(),INTERVAL 2 MINUTE) WHERE session_id=?',[pair.id]);state=(await req('/pairs/'+pair.id)).data;assert.equal(state.devices.find(d=>d.role==='phone').online,false);assert.equal(state.devices.find(d=>d.role==='computer').online,true);const beat=await req('/pairs/'+pair.id+'/heartbeat','POST',{role:'phone',mobile:accepted.mobile,device_name:'Alice Android'});assert.equal(beat.status,200);assert.equal(beat.data.devices.find(d=>d.role==='phone').name,'Alice Android');assert.equal(beat.data.devices.find(d=>d.role==='phone').online,true);const actor=(await req('/auth')).data.user.id;await service.transaction(async db=>{try{await db.q("SET time_zone='+08:00'");const state=await require('../lib/pair-devices').heartbeat(db,pair.id,{role:'phone',mobile:accepted.mobile,device_name:'Alice Android'},actor);assert.equal(state.devices.find(d=>d.role==='phone').online,true,'Presence uses UTC even when MySQL uses Malaysia time');assert.ok(Date.parse(state.expires_at)>Date.now()+29*86400000);}finally{await db.q("SET time_zone='+00:00'");}});await assert.rejects(require('../lib/pair-devices').verifyPhone(service,pair.id,accepted.mobile,'another-employee'),/another employee/);assert.equal((await req('/pairs/'+pair.id+'/heartbeat','POST',{role:'phone',mobile:'wrong',device_name:'Unknown'})).status,410);assert.equal((await req('/pairs/'+pair.id+'/heartbeat','POST',{role:'phone',mobile:accepted.mobile,device_name:'X'.repeat(81)})).status,400);await req('/pairs/'+pair.id,'DELETE');assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_pair_devices')).n),0);});

test('MySQL workflow: paired queues synchronize both directions in order, retry once and confirm peer receipt',{skip:!enabled},async t=>{const {req,service}=await setup(t),user=(await req('/auth')).data.user.id;const p=(await req('/products','POST',{customer:{name:'BIDIRECTIONAL QUEUE',address:'TEST'},company:'DE',product_type:'ATS',brand:'B',serial_no:crypto.randomUUID(),details:{}})).data;const pair=(await req('/pairs','POST',{})).data,token=new URL(pair.link).hash.split('pair=')[1],phone=(await req('/pairs/'+pair.id+'/accept','POST',{pair:token})).data;const path='/pairs/'+pair.id,pc={role:'computer'},mobile={role:'phone',mobile:phone.mobile},request_id=crypto.randomUUID(),body={...pc,action:'add',product_ids:[p.id],request_id};const first=await req(path+'/queue-events','POST',body);assert.equal(first.status,200);assert.equal((await req(path+'/queue-events','POST',body)).data.event_id,first.data.event_id,'retry must not duplicate event');let read=await req(path+'/queue-read','POST',{...mobile,after:0});assert.equal(read.status,200);assert.equal(read.data.events.length,1);assert.equal(read.data.events[0].products[0].id,p.id);assert.equal((await req(path+'/queue-status','POST',{...pc,event_id:first.data.event_id})).data.received,false);assert.equal((await req(path+'/queue-ack','POST',{...mobile,through:first.data.event_id})).status,200);assert.equal((await req(path+'/queue-status','POST',{...pc,event_id:first.data.event_id})).data.received,true);const removed=(await req(path+'/queue-events','POST',{...mobile,action:'remove',product_ids:[p.id],request_id:crypto.randomUUID()})).data;const again=(await req(path+'/queue-events','POST',{...pc,action:'add',product_ids:[p.id],request_id:crypto.randomUUID()})).data;read=await req(path+'/queue-read','POST',{...pc,after:first.data.event_id});assert.deepEqual(read.data.events.map(e=>e.action),['remove','add']);assert.ok(removed.event_id<again.event_id);assert.equal((await req(path+'/queue-read','POST',{role:'phone',mobile:'wrong',after:0})).status,410);assert.equal((await req(path+'/queue-ack','POST',{...mobile,through:again.event_id+100})).status,400);await assert.rejects(require('../lib/queue-sync').read(service,pair.id,{...pc,after:0},crypto.randomUUID()),/not found/);assert.equal((await req(path+'/queue-status','POST',{...mobile,event_id:first.data.event_id})).status,403);const book=new Excel.Workbook(),sheet=book.addWorksheet('Records');sheet.addRow(['Name','Address','Type','Brand','S/No']);sheet.addRow(['SHARED IMPORT','TEST ROAD','ATS','TEST','QUEUE-IMPORT']);const bytes=await book.xlsx.writeBuffer(),imports=require('../lib/import'),batches=require('../lib/import-batches');await service.transaction(db=>imports.commit(db,bytes,'AUTO',user));const imported=(await service.products('QUEUE-IMPORT',0)).items[0];await req(path+'/queue-events','POST',{...pc,action:'add',product_ids:[imported.id],request_id:crypto.randomUUID()});const cleared=await service.transaction(db=>batches.clear(db,null,user));assert.equal(cleared.removed_products,0,'Active shared queue products are protected when clearing imports');assert.equal((await service.product(imported.id)).id,imported.id);await req(path,'DELETE');assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_pair_queue_events')).n),0);assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_pair_queue_receipts')).n),0);});

test('MySQL workflow: six counterpoise rows keep blank positions in saved products, previews and both company PDFs',{skip:!enabled},async t=>{const {req}=await setup(t),values='\n2.5\n\n4.5\n\n6.5',{getDocument}=await import('pdfjs-dist/legacy/build/pdf.mjs');for(const company of ['DE','MCM']){const p=(await req('/products','POST',{customer:{name:'COUNTERPOISE '+company,address:'ROAD'},company,product_type:'ATP (M)',brand:'TEST',serial_no:crypto.randomUUID(),details:{counterpoise_weights:values}})).data;assert.equal(p.details.counterpoise_weights,values);const pdf=await req('/jobs/preview','POST',{company,product_ids:[p.id],stamping_date:'2026-11-12',product_overrides:{[p.id]:{details:{counterpoise_weights:values}}}});assert.equal(pdf.status,200);const task=getDocument({data:new Uint8Array(pdf.data),useSystemFonts:true});try{const doc=await task.promise,page=await doc.getPage(1),content=await page.getTextContent(),items=content.items.filter(x=>['2.5','4.5','6.5'].includes(x.str));assert.equal(items.length,3);items.sort((a,b)=>b.transform[5]-a.transform[5]);assert.deepEqual(items.map(x=>x.str),['2.5','4.5','6.5']);assert.ok(Math.abs((items[0].transform[5]-items[1].transform[5])-33)<2,'Row (2) and (4) keep their original printed positions');assert.ok(Math.abs((items[1].transform[5]-items[2].transform[5])-39)<2,'Row (6) stays below row (4)');}finally{await task.destroy();}}});

test('MySQL workflow: import uses preferred registration as old, defaults Shop/Out to O, and repairs without overwriting completed records',{skip:!enabled},async t=>{const {req,service}=await setup(t),actor=(await req('/auth')).data.user.id,imports=require('../lib/import'),book=new Excel.Workbook(),sheet=book.addWorksheet('Records');sheet.addRow(['Name','Address','Type','Brand','Model','S/No','Date','No. Daftar Lama','No. Daftar Baru','Shop/Out']);for(const [serial,old,newer,shop]of [['BOTH','OLD1','NEW1',''],['OLD','OLD2','','S'],['NEW','','CRA003','O'],['INVALID','OLD4','','unknown']])sheet.addRow(['REG '+serial,'ROAD','ATN','TEST','M',serial,'2025-01-01',old,newer,shop]);const bytes=await book.xlsx.writeBuffer(),commit=(opts={})=>service.transaction(db=>imports.commit(db,bytes,'AUTO',actor,opts));const first=await commit();assert.equal(first.created_products,4);const products=(await service.products('REG ',0)).items,bySerial=Object.fromEntries(products.map(p=>[p.serial_no,p]));for(const serial of ['BOTH','OLD','NEW','INVALID'])assert.equal(bySerial[serial].details.new_reg,'');assert.equal(bySerial.BOTH.details.old_reg,'NEW1');assert.equal(bySerial.OLD.details.old_reg,'OLD2');assert.equal(bySerial.NEW.details.old_reg,'CRA003');assert.equal(bySerial.NEW.company,'MCM');assert.equal(bySerial.BOTH.details.shop_out,'O');assert.equal(bySerial.OLD.details.shop_out,'S');assert.equal(bySerial.INVALID.details.shop_out,'O');const hash=require('../lib/util').hash(bytes.toString('base64')),oldDetails={...bySerial.BOTH.details,source_date:'2026-01-01',old_reg:'OLD1',new_reg:'NEW1',shop_out:''};await service.q('UPDATE app_products SET details=? WHERE id=?',[JSON.stringify(oldDetails),bySerial.BOTH.id]);await service.q('UPDATE app_imports SET result=? WHERE file_hash=?',[JSON.stringify({...first,mapping_version:5}),hash]);const repaired=await commit();assert.equal(repaired.created_products,0);assert.equal(repaired.history_rows,0);let repairedProduct=await service.product(bySerial.BOTH.id);assert.equal(repairedProduct.details.old_reg,'NEW1');assert.equal(repairedProduct.details.new_reg,'');assert.equal(repairedProduct.details.shop_out,'O');const done=await req('/jobs/complete','POST',{company:'DE',product_ids:[repairedProduct.id],stamping_date:'2026-11-12',request_id:crypto.randomUUID(),product_versions:{[repairedProduct.id]:repairedProduct.version},customer_versions:{[repairedProduct.id]:repairedProduct.customer_version},product_overrides:{[repairedProduct.id]:{details:{new_reg:'COMPLETED1'}}}});assert.equal(done.status,200,JSON.stringify(done.data));await commit({repairMissing:true});const live=await service.product(repairedProduct.id);assert.equal(live.details.new_reg,'COMPLETED1');assert.equal(live.details.old_reg,'NEW1');const record=(await req('/jobs/'+done.data.id)).data.snapshot.products[0];assert.equal(record.details.new_reg,'COMPLETED1');assert.equal(record.details.old_reg,'NEW1');});

