 assert.equal((await req('/products/'+p.id+'/queue-details','PUT',save)).data.version,latest.version);assert.equal((await req('/products/'+p.id+'/queue-details','PUT',{...save,request_id:crypto.randomUUID()})).status,409);
 const bad=await req('/products/'+p.id+'/queue-details','PUT',{...save,version:latest.version,customer_version:latest.customer_version,request_id:crypto.randomUUID(),patch:{brand:'SHOULD ROLLBACK',details:{stamping_fee:'-1'}}});assert.equal(bad.status,400);assert.equal((await req('/products/'+p.id)).data.brand,'UPDATED');assert.equal(Number((await service.one('SELECT COUNT(*) AS n FROM app_jobs')).n),0);
