test('MySQL workflow: each new product records its own first Save day independently of an older customer',{skip:!enabled},async t=>{
 const {req,service}=await setup(t),actor=(await req('/auth')).data.user.id,dates=require('../../frontend/table-sort');
 async function at(instant,action){return service.transaction(async db=>{await db.q('SET timestamp=?',[Date.parse(instant)/1000]);try{return await action(db);}finally{await db.q('SET timestamp=DEFAULT');}});}
 const customer=await at('2026-10-01T02:00:00Z',db=>db.createManualCustomer({name:'OLDER CUSTOMER',address:'ROAD'},actor));
 const input={customer_id:customer.id,company:'DE',product_type:'ATN',brand:'TEST',model:'M',details:{capacity:'10KG'},created_at:customer.created_at,created_epoch:1};
 const first=await at('2026-11-20T02:00:00Z',db=>db.saveProduct(null,{...input,serial_no:'FIRST-'+crypto.randomUUID()},actor));
 const second=await at('2026-11-21T02:00:00Z',db=>db.saveProduct(null,{...input,serial_no:'SECOND-'+crypto.randomUUID()},actor));
 assert.equal(first.customer_id,second.customer_id);assert.notEqual(first.id,second.id);assert.equal(dates.createdDate(first),'20/11/2026');assert.equal(dates.createdDate(second),'21/11/2026');assert.equal(Number(first.created_epoch),Date.parse('2026-11-20T02:00:00Z')/1000);assert.equal(Number(second.created_epoch),Date.parse('2026-11-21T02:00:00Z')/1000);
 const edited=await at('2026-11-22T02:00:00Z',db=>db.saveProduct(first.id,{...first,model:'UPDATED MODEL',created_at:second.created_at},actor));assert.equal(dates.createdDate(edited),'20/11/2026');assert.equal(dates.savedDate(first),'20/11/2026');assert.equal(dates.savedDate(second),'21/11/2026');assert.equal(dates.savedDate(edited),'22/11/2026');const viewed=(await req('/products/'+first.id)).data;assert.equal(dates.savedDate(viewed),'22/11/2026');assert.equal(viewed.updated_at,edited.updated_at);for(const direction of ['asc','desc']){const sorted=await service.products('OLDER CUSTOMER',0,'name',direction);assert.deepEqual(sorted.items.map(p=>p.id),[second.id,first.id]);}assert.equal(edited.created_at,first.created_at);assert.equal((await service.customer(customer.id)).created_at,customer.created_at);
 for(const product of [first,second]){const loaded=(await req('/products/'+product.id)).data;assert.equal(loaded.created_at,product.created_at);assert.equal(dates.createdDate(loaded),dates.createdDate(product));}
});

test('MySQL workflow: existing product dates reset once to 20 November with backup and future saves survive restarts',{skip:!enabled},async t=>{const {req,service,pool}=await setup(t),baseline=require('../lib/product-date-baseline'),dates=require('../../frontend/table-sort'),actor=(await req('/auth')).data.user.id;const p=(await req('/products','POST',{customer:{name:'BASELINE OWNER',address:'ROAD'},company:'DE',product_type:'ATN',brand:'TEST',serial_no:crypto.randomUUID(),details:{capacity:'10KG'}})).data;await service.q('DELETE FROM app_data_migrations WHERE name=?',[baseline.migration]);await service.q("UPDATE app_products SET updated_at=FROM_UNIXTIME(?) WHERE id=?",[Date.parse('2026-11-21T17:25:00Z')/1000,p.id]);const before=await service.product(p.id);const counts=await Promise.all([baseline.apply(pool),baseline.apply(pool)]);assert.equal(counts.reduce((a,b)=>a+b,0),1);const corrected=await service.product(p.id);assert.equal(dates.savedDate(corrected),'20/11/2026');assert.equal(corrected.created_at,before.created_at);assert.deepEqual(corrected.details,before.details);assert.equal(corrected.version,before.version+1);assert.equal(Number(corrected.saved_epoch),Date.parse('2026-11-19T17:25:00Z')/1000);const backup=await service.one('SELECT original_saved_epoch FROM app_product_date_backup WHERE product_id=?',[p.id]);assert.equal(Number(backup.original_saved_epoch),Number(before.saved_epoch));const edited=await service.transaction(async db=>{await db.q('SET timestamp=?',[Date.parse('2026-11-22T02:00:00Z')/1000]);try{return await db.saveProduct(p.id,{...corrected,model:'NEW MODEL'},actor);}finally{await db.q('SET timestamp=DEFAULT');}});assert.equal(dates.savedDate(edited),'22/11/2026');const added=await service.saveProduct(null,{customer_id:p.customer_id,company:'DE',product_type:'ATS',brand:'NEW',details:{}},actor);assert.equal(await baseline.apply(pool),0);assert.equal((await service.product(p.id)).updated_at,edited.updated_at);assert.equal((await service.product(added.id)).updated_at,added.updated_at);});

test('MySQL workflow: Print List leaves new registration blank until entered and Complete preserves final number',{skip:!enabled},async t=>{const {req,service}=await setup(t),p=(await req('/products','POST',{customer:{name:'LIST OWNER',address:'ROAD'},company:'DE',product_type:'ATN',brand:'TEST',serial_no:crypto.randomUUID(),details:{old_reg:'P999',new_reg:'C123'}})).data,input={company:'DE',product_ids:[p.id],stamping_date:'2026-11-21',workflow_mode:true};const {getDocument}=await import('pdfjs-dist/legacy/build/pdf.mjs');async function numbers(response){assert.equal(response.status,200);const task=getDocument({data:new Uint8Array(response.data),useSystemFonts:true});try{const doc=await task.promise,items=(await(await doc.getPage(1)).getTextContent()).items;return items.filter(x=>/C123|N456|P999/.test(x.str));}finally{await task.destroy();}}for(const workflow_mode of [true,false]){const items=await numbers(await req('/jobs/list-preview','POST',{...input,workflow_mode}));assert.deepEqual(items.map(x=>x.str),['C123']);assert.ok(items[0].transform[4]<607.17,'Current number stays in old-registration column');}assert.equal((await service.product(p.id)).version,p.version);const entered={...input,product_overrides:{[p.id]:{details:{new_reg:'N456'}}}};assert.deepEqual((await numbers(await req('/jobs/list-preview','POST',entered))).map(x=>x.str),['C123','N456']);const save=await req('/products/'+p.id+'/queue-details','PUT',{version:p.version,customer_version:p.customer_version,request_id:crypto.randomUUID(),patch:{details:{new_reg:'N456'}}});assert.equal(save.status,200);assert.deepEqual((await numbers(await req('/jobs/list-preview','POST',input))).map(x=>x.str),['C123','N456']);const done=await req('/jobs/complete','POST',{...input,request_id:crypto.randomUUID(),product_versions:{[p.id]:save.data.version},customer_versions:{[p.id]:save.data.customer_version}});assert.equal(done.status,200);assert.equal((await service.product(p.id)).details.new_reg,'N456');assert.deepEqual((await numbers(await req('/jobs/'+done.data.id+'/list.pdf'))).map(x=>x.str),['C123','N456']);});

test('MySQL workflow: Complete Record sorts globally before pagination and validates sort inputs',{skip:!enabled},async t=>{const {req,service}=await setup(t),job=crypto.randomUUID(),products=Array.from({length:55},(_,i)=>({id:crypto.randomUUID(),name:'OWNER '+String(54-i).padStart(2,'0'),address:'ROAD',area:'AREA',brand:'TEST',product_type:'ATN',details:{capacity:(i+1)+'KG',new_reg:'REG'+i}})),snapshot={settings:{stamping_date:'2026-11-21',list_entries:Object.fromEntries(products.map((p,i)=>[p.id,{stamping_fee:String(i+1)}]))},products},actor=(await req('/auth')).data.user.id;await service.q('INSERT INTO app_jobs(id,request_id,title,stamping_date,snapshot,pdf,created_by) VALUES (?,?,?,?,?,?,?)',[job,crypto.randomUUID(),'SORT RECORDS','2026-11-21',JSON.stringify(snapshot),Buffer.from('test'),actor]);let a=await req('/records?sort=name&direction=asc'),b=await req('/records?sort=name&direction=asc&page=1');assert.equal(a.status,200);assert.equal(a.data.items[0].name,'OWNER 00');assert.equal(a.data.items.at(-1).name,'OWNER 49');assert.equal(b.data.items[0].name,'OWNER 50');assert.equal((await req('/records?sort=fee&direction=desc')).data.items[0].fee,'55');assert.equal((await req('/records?sort=capacity&direction=asc')).data.items[0].details.capacity,'1KG');assert.equal((await req('/records?sort=date&direction=desc&from=2026-11-22')).data.total,0);for(const key of ['date','name','address','area','type','condition','brand','model','serial','capacity','old_reg','shop_out','fee'])assert.equal((await req('/records?sort='+key+'&direction=desc')).status,200,key);assert.equal((await req('/records?sort=DROP')).status,400);assert.equal((await req('/records?sort=name&direction=DROP')).status,400);});
